 beforelogs=json.loads((O/(domain+'_before_checks.json')).read_text())['logs'];old={(x.get('name'),str(x.get('message'))) for x in beforelogs};new=[x for x in result['checks_restored']['logs'] if (x.get('name'),str(x.get('message'))) not in old]
 bm={e['entry_id']:e for e in before['entries']};changed=[{'domain':e['domain'],'title':e['title'],'before':bm[e['entry_id']]['state'],'after':e['state']} for e in during['entries'] if e['entry_id'] in bm and e['entry_id']!=result['entry_id'] and e['state']!=bm[e['entry_id']]['state']]
